<?php
declare(strict_types=1);namespace App\Services;use App\Core\{Audit,Auth,Database,Http,Settings};use PDO;final class AuthService{public function findUserByEmail(string $email):?array{$s=Database::pdo()->prepare('SELECT u.*,r.code role_code,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.deleted_at IS NULL LIMIT 1');$s->execute([strtolower($email)]);return $s->fetch()?:null;}public function register(string $email,string $name,?string $phone):array{$email=strtolower(trim($email));return Database::transaction(function(PDO $pdo)use($email,$name,$phone){$e=$this->findUserByEmail($email);if($e)return $e;$rid=(int)$pdo->query("SELECT id FROM roles WHERE code='SOLICITANTE' LIMIT 1")->fetchColumn();$s=$pdo->prepare("INSERT INTO users(email,name,phone,role_id,account_status,active,registered_at,created_at,updated_at) VALUES(?,?,?,?,'PENDING_ASSIGNMENT',1,NOW(),NOW(),NOW())");$s->execute([$email,trim($name),$phone?:null,$rid]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO user_role_history(user_id,role_id,started_at,reason,created_at) VALUES(?,?,NOW(),?,NOW())')->execute([$id,$rid,'Autorregistro inicial']);Audit::log('USER_REGISTERED','user',$id,null,['email'=>$email,'status'=>'PENDING_ASSIGNMENT']);return $this->findUserByEmail($email);});}public function sendOtp(string $email):void{$email=strtolower(trim($email));$this->rateLimit($email);$u=$this->findUserByEmail($email);if(!$u||!$u['active']||in_array($u['account_status'],['SUSPENDED','INACTIVE'],true))throw new \RuntimeException('La cuenta no está disponible.');$pdo=Database::pdo();$lock=$pdo->prepare('SELECT blocked_until FROM otp_requests WHERE email=? AND blocked_until>NOW() ORDER BY id DESC LIMIT 1');$lock->execute([$email]);if($lock->fetchColumn()!==false)throw new \RuntimeException('Acceso bloqueado temporalmente por intentos fallidos.');$len=6;$code=(string)random_int(10**($len-1),10**$len-1);$hash=password_hash($code,PASSWORD_DEFAULT);$mins=max(2,min(30,(int)Settings::get('otp_expiration_minutes',10)));$max=max(3,min(10,(int)Settings::get('otp_max_attempts',5)));$exp=(new \DateTimeImmutable("+{$mins} minutes"))->format('Y-m-d H:i:s');$pdo->prepare('UPDATE otp_requests SET consumed_at=NOW() WHERE email=? AND consumed_at IS NULL')->execute([$email]);$s=$pdo->prepare('INSERT INTO otp_requests(user_id,email,code_hash,expires_at,max_attempts,requested_ip,user_agent,created_at) VALUES(?,?,?,?,?,?,?,NOW())');$s->execute([(int)$u['id'],$email,$hash,$exp,$max,Http::ip(),Http::userAgent()]);Audit::log('OTP_REQUESTED','user',(int)$u['id'],null,null,['email'=>$email]);try{(new MailService())->sendOtp($email,$code,$mins);}catch(\Throwable $e){$pdo->prepare('UPDATE otp_requests SET consumed_at=NOW() WHERE id=?')->execute([(int)$pdo->lastInsertId()]);throw $e;}$_SESSION['otp_email']=$email;}public function verify(string $email,string $code):array{$email=strtolower(trim($email));$r=Database::transaction(function(PDO $pdo)use($email,$code){$s=$pdo->prepare('SELECT * FROM otp_requests WHERE email=? AND consumed_at IS NULL ORDER BY id DESC LIMIT 1 FOR UPDATE');$s->execute([$email]);$o=$s->fetch();if(!$o)return ['error'=>'Solicita un código nuevo.'];if($o['blocked_until']&&strtotime((string)$o['blocked_until'])>time())return ['error'=>'Código bloqueado temporalmente.'];if(strtotime((string)$o['expires_at'])<time()){$pdo->prepare('UPDATE otp_requests SET consumed_at=NOW() WHERE id=?')->execute([(int)$o['id']]);return ['error'=>'El código venció.'];}if(!password_verify($code,(string)$o['code_hash'])){$a=(int)$o['attempts']+1;$block=$a>=(int)$o['max_attempts']?date('Y-m-d H:i:s',time()+900):null;$pdo->prepare('UPDATE otp_requests SET attempts=?,blocked_until=? WHERE id=?')->execute([$a,$block,(int)$o['id']]);return ['error'=>$block?'Demasiados intentos. Intenta en 15 minutos.':'Código incorrecto.'];}$pdo->prepare('UPDATE otp_requests SET consumed_at=NOW() WHERE id=?')->execute([(int)$o['id']]);$pdo->prepare('UPDATE users SET verified_at=COALESCE(verified_at,NOW()),last_login_at=NOW(),updated_at=NOW() WHERE id=?')->execute([(int)$o['user_id']]);$u=$this->findUserByEmail($email);$sid=(new SessionService())->create((int)$u['id']);return ['user'=>$u,'session_id'=>$sid];});if(isset($r['error'])){Audit::log('OTP_FAILED',null,null,null,null,['email'=>$email]);throw new \RuntimeException($r['error']);}Auth::login($r['user'],(int)$r['session_id']);Audit::log('LOGIN_SUCCESS','user',(int)$r['user']['id']);unset($_SESSION['otp_email']);return $r['user'];}private function rateLimit(string $email):void{$pdo=Database::pdo();$s=$pdo->prepare('SELECT COUNT(*) FROM otp_requests WHERE email=? AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$s->execute([$email]);$i=$pdo->prepare('SELECT COUNT(*) FROM otp_requests WHERE requested_ip=? AND created_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$i->execute([Http::ip()]);if((int)$s->fetchColumn()>=5||(int)$i->fetchColumn()>=20)throw new \RuntimeException('Límite de códigos alcanzado. Espera 15 minutos.');}}
